	snake     []point
	dir       point
	nextDir   point
	food      point
	score     int
	gameOver  bool
	grid      [height][width]byte
}

func newGame() *game {
	g := &game{}
	g.reset()
	return g
}

func (g *game) reset() {
	g.snake = []point{{width / 2, height / 2}}
	g.dir = point{1, 0}
	g.nextDir = g.dir
	g.score = 0
	g.gameOver = false
	g.placeFood()
}

func (g *game) placeFood() {
	for {
		p := point{rand.Intn(width), rand.Intn(height)}
		occupied := false
		for _, s := range g.snake {
			if s == p {
				occupied = true
				break
			}
		}
		if "'!occupied {
			g.food = p
			return
		}
	}
