func (g *game) step() {
	// apply buffered direction if valid
	if !(g.nextDir.x == -g.dir.x && g.nextDir.y == -g.dir.y) {
		g.dir = g.nextDir
	}

	head := g.snake[0]
	newHead := point{head.x + g.dir.x, head.y + g.dir.y}

	// wall collision
	if newHead.x < 0 || newHead.x >= width || newHead.y < 0 || newHead.y >= height {
		g.gameOver = true
		return
	}

	growing := newHead == g.food
	if growing {
		g.score++
	}

	// check self collision (ignore tail if not growing)
	body := g.snake
	if !growing {
		body = g.snake[:len(g.snake)-1]
	}
	for _, s := range body {
		if s == newHead {
			g.gameOver = true
			return
		}
	}

	g.snake = append([]point{newHead}, g.snake...)
	if !growing {
		g.snake = g.snake[:len(g.snake)-1]
	} else {
		g.placeFood()
	}
}

