		return nil, errno
	}

	return func() {
		syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd),
			uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&old)))
	}, nil
}

func main() {
	restore, err := makeRaw(int(os.Stdin.Fd()))
	if err != nil {
		fmt.Fprintln(os.Stderr, "error entering raw mode:", err)
		return
	}
	defer restore()
	defer fmt.Print("'"\\x1b[?25h\\x1b[0m\\n\") // show cursor + reset

	rand.Seed(time.Now().UnixNano())
	g := newGame()
	g.render()

	input := make(chan byte, 1)
	go func() {
		buf := make([]byte, 1)
		for {
			n, err := os.Stdin.Read(buf)
			if err "'!= nil || n == 0 {
				close(input)
				return
			}
			select {
			case input <- buf[0]:
			default:
			}
		}
	}()

	ticker := time.NewTicker(80 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case b, ok := <-input:
			if !ok {
				return
			}
			switch b {
			case '"'q':
				return
			case 'r':
				g.reset()
				g.render()
			case 'w', 'W', 'k':
				g.nextDir = point{0, -1}
			case 's', 'S', 'j':
				g.nextDir = point{0, 1}
			case 'a', 'A', 'h':
				g.nextDir = point{-1, 0}
			case 'd', 'D', 'l':
