					case 'A':
						g.nextDir = point{0, -1}
					case 'B':
						g.nextDir = point{0, 1}
					case 'C':
						g.nextDir = point{1, 0}
					case 'D':
						g.nextDir = point{-1, 0}
					}
				}
			}
			if "'!g.gameOver {
				g.render()
			}
		case <-ticker.C:
			if !g.gameOver {
				g.step()
				g.render()
			}
		}
	}
}
